<script setup lang="ts">import{gradientPickerStopClassName}from'@fex-design/styles/color-picker';import{cn}from'@fex/utils';import{computed,useAttrs}from'vue';import{useGradientPicker}from'./context';defineOptions({inheritAttrs:false});const props=defineProps<{id:string}>(),attrs=useAttrs(),picker=useGradientPicker(),stop=computed(()=>picker.snapshot.value.value.stops.find(item=>item.id===props.id));function down(event:PointerEvent){if(picker.snapshot.value.disabled)return;(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);picker.controller.selectStop(props.id);picker.controller.beginInteraction('stop-move')}function move(event:PointerEvent){const element=event.currentTarget as HTMLElement;if(!element.hasPointerCapture(event.pointerId))return;const rect=element.parentElement!.getBoundingClientRect();picker.controller.moveStop(props.id,(event.clientX-rect.left)/rect.width)}function up(event:PointerEvent){const element=event.currentTarget as HTMLElement;if(element.hasPointerCapture(event.pointerId)){element.releasePointerCapture(event.pointerId);picker.controller.completeInteraction()}}</script><template><button v-if="stop" v-bind="attrs" type="button" :disabled="picker.snapshot.value.disabled" :data-selected="picker.snapshot.value.selectedStopId===id||undefined" :class="cn(gradientPickerStopClassName,attrs.class as string|undefined)" :style="[{left:`clamp(6px, ${stop.position*100}%, calc(100% - 6px))`,'--gradient-stop-color':stop.color.toString('rgb')},attrs.style]" @pointerdown="down" @pointermove="move" @pointerup="up"/></template>
